package com.oms.order.service;

import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.ExchangeService.map;

/** Local indexed resolution only; channel never selects another service's datasource or scans JSON. */
@Service public class OrderPlatformLogWorkspace {
    @Resource OrderRepository repository;
    public OrderPlatformLogWorkspace(){}
    public OrderPlatformLogWorkspace(OrderRepository repository){this.repository=repository;}
    private void ref(List<Map<String,Object>> list,String type,Object raw){String number=raw==null?"":raw.toString();if(number.isEmpty())return;Map<String,Object> value=map("type",type,"number",number);if(!list.contains(value))list.add(value);require(list.size()<=300,"关联单据过多，请使用换货单或发货单号查询");}
    public Map<String,Object> exchangeContext(String company,long channel,Map<String,Object> args){List<Map<String,Object>> refs=new ArrayList<>();String dispute=text(args,"dispute_id");if(!dispute.isEmpty())ref(refs,"PLATFORM_EXCHANGE",dispute);Map<String,Object> context=map("source_service","order","trigger_source","BUSINESS","refs",refs);if(dispute.isEmpty())return context;List<Map<String,Object>> cases=repository.db().query("SELECT e.id,e.exchange_sn,e.platform_tid,e.platform_oid,e.approved_version,e.fulfillment_round,e.platform_request,e.platform_operation,o.order_sn FROM oms_exchange e LEFT JOIN oms_order o ON o.company_code=e.company_code AND o.id=e.order_id WHERE e.company_code=? AND e.channel_id=? AND e.dispute_id=? AND e.source_kind='PLATFORM'",ROW,company,channel,dispute);if(cases.size()==1){Map<String,Object> e=cases.get(0);ref(refs,"EXCHANGE",e.get("exchange_sn"));ref(refs,"OMS_ORDER",e.get("order_sn"));ref(refs,"PLATFORM_TID",e.get("platform_tid"));ref(refs,"PLATFORM_OID",e.get("platform_oid"));if(e.get("platform_request")!=null&&!"NONE".equals(text(e,"platform_operation")))context.put("operation_id","EXOP"+hash(e.get("id")+":"+e.get("approved_version")+":"+e.get("fulfillment_round")+":"+e.get("platform_request")).substring(0,40));}return context;}
    public List<Map<String,Object>> resolve(String company,Map<String,Object> input){String type=text(input,"type"),number=text(input,"number");require(number.matches("[A-Za-z0-9_:.\\-]{1,128}"),"业务单号无效");List<Map<String,Object>> result=new ArrayList<>();
        if("AUTO".equals(type)){for(String candidate:Arrays.asList("EXCHANGE","SHIPMENT","OMS_ORDER","PLATFORM_TID","PLATFORM_OID","PLATFORM_EXCHANGE","REFUND","PLATFORM_REFUND"))for(Map<String,Object> r:resolve(company,map("type",candidate,"number",number)))ref(result,text(r,"type"),r.get("number"));return result;}
        ref(result,type,number);
        if("REFUND".equals(type)||"PLATFORM_REFUND".equals(type)){String field="REFUND".equals(type)?"b.refund_sn":"p.refund_id";for(Map<String,Object> row:repository.db().query("SELECT p.refund_id,p.platform_tid,p.platform_oid,b.refund_sn,b.order_sn FROM oms_platform_refund p LEFT JOIN oms_refund b ON b.company_code=p.company_code AND b.platform_refund_id=p.id WHERE p.company_code=? AND "+field+"=? LIMIT 100",ROW,company,number)){ref(result,"REFUND",row.get("refund_sn"));ref(result,"PLATFORM_REFUND",row.get("refund_id"));ref(result,"OMS_ORDER",row.get("order_sn"));ref(result,"PLATFORM_TID",row.get("platform_tid"));ref(result,"PLATFORM_OID",row.get("platform_oid"));}return result;}

        if("EXCHANGE".equals(type)||"PLATFORM_EXCHANGE".equals(type)){for(Map<String,Object> p:repository.db().query("SELECT p.dispute_id,p.platform_tid,p.platform_oid,e.exchange_sn,o.order_sn FROM oms_platform_exchange p LEFT JOIN oms_exchange e ON e.company_code=p.company_code AND e.id=p.business_exchange_id LEFT JOIN oms_order o ON o.company_code=p.company_code AND o.id=p.order_id WHERE p.company_code=? AND "+("EXCHANGE".equals(type)?"e.exchange_sn":"p.dispute_id")+"=? LIMIT 100",ROW,company,number)){ref(result,"PLATFORM_EXCHANGE",p.get("dispute_id"));ref(result,"PLATFORM_TID",p.get("platform_tid"));ref(result,"PLATFORM_OID",p.get("platform_oid"));ref(result,"EXCHANGE",p.get("exchange_sn"));ref(result,"OMS_ORDER",p.get("order_sn"));}for(Map<String,Object> e:repository.db().query("SELECT exchange_sn,dispute_id FROM oms_exchange WHERE company_code=? AND "+("EXCHANGE".equals(type)?"exchange_sn":"dispute_id")+"=? LIMIT 2",ROW,company,number)){ref(result,"EXCHANGE",e.get("exchange_sn"));ref(result,"PLATFORM_EXCHANGE",e.get("dispute_id"));}return result;}
        if("SHIPMENT".equals(type)){for(Map<String,Object> row:repository.db().query("SELECT id,exchange_id,business_type FROM oms_order_shipment WHERE company_code=? AND shipment_sn=? LIMIT 2",ROW,company,number)){shipmentRefs(company,number(row,"id"),result);if("EXCHANGE".equals(text(row,"business_type")))for(Map<String,Object> e:repository.db().query("SELECT exchange_sn,dispute_id FROM oms_exchange WHERE company_code=? AND id=?",ROW,company,row.get("exchange_id"))){ref(result,"EXCHANGE",e.get("exchange_sn"));ref(result,"PLATFORM_EXCHANGE",e.get("dispute_id"));}}return result;}
        if("OMS_ORDER".equals(type)||"PLATFORM_TID".equals(type)){String field="OMS_ORDER".equals(type)?"order_sn":"platform_tid";List<Map<String,Object>> orders=repository.db().query("SELECT id,order_sn,platform_tid FROM oms_order WHERE company_code=? AND "+field+"=? LIMIT 101",ROW,company,number);require(orders.size()<=100,"订单关联较多，请使用执行单号查询");for(Map<String,Object> order:orders){ref(result,"OMS_ORDER",order.get("order_sn"));ref(result,"PLATFORM_TID",order.get("platform_tid"));List<Map<String,Object>> cases=repository.db().query("SELECT exchange_sn,dispute_id FROM oms_exchange WHERE company_code=? AND order_id=? LIMIT 101",ROW,company,order.get("id"));require(cases.size()<=100,"换货记录较多，请使用换货单号查询");for(Map<String,Object> e:cases){ref(result,"EXCHANGE",e.get("exchange_sn"));ref(result,"PLATFORM_EXCHANGE",e.get("dispute_id"));}for(Map<String,Object> sh:repository.db().query("SELECT shipment_sn FROM oms_order_shipment WHERE company_code=? AND order_id=? LIMIT 101",ROW,company,order.get("id")))ref(result,"SHIPMENT",sh.get("shipment_sn"));}return result;}
        if("PLATFORM_OID".equals(type)){for(Map<String,Object> e:repository.db().query("SELECT exchange_sn,dispute_id FROM oms_exchange WHERE company_code=? AND platform_oid=? LIMIT 101",ROW,company,number)){ref(result,"EXCHANGE",e.get("exchange_sn"));ref(result,"PLATFORM_EXCHANGE",e.get("dispute_id"));}}return result;
    }
    private void shipmentRefs(String company,long id,List<Map<String,Object>> refs){for(Map<String,Object> p:repository.db().query("SELECT package_code,express_code FROM oms_order_shipment_package WHERE company_code=? AND shipment_id=? LIMIT 100",ROW,company,id)){ref(refs,"PACKAGE",p.get("package_code"));ref(refs,"WAYBILL",p.get("express_code"));}for(Map<String,Object> task:repository.db().query("SELECT request_id FROM oms_order_platform_shipping_task WHERE company_code=? AND shipment_id=? LIMIT 100",ROW,company,id))ref(refs,"TASK",task.get("request_id"));}
    public List<Map<String,Object>> states(String company,List<Map<String,Object>> refs){require(refs!=null&&refs.size()<=100,"业务查询最多100个单号");List<Map<String,Object>> result=new ArrayList<>();for(String type:Arrays.asList("OMS_ORDER","EXCHANGE","SHIPMENT","PLATFORM_EXCHANGE","PLATFORM_TID")){Set<String> values=new LinkedHashSet<>();for(Map<String,Object> ref:refs){require(text(ref,"number").matches("[A-Za-z0-9_:.\\-]{1,128}"),"业务单号无效");if(type.equals(text(ref,"type")))values.add(text(ref,"number"));}if(values.isEmpty())continue;String businessType=type.equals("PLATFORM_EXCHANGE")?"EXCHANGE":type.equals("PLATFORM_TID")?"OMS_ORDER":type;String table=businessType.equals("OMS_ORDER")?"oms_order":businessType.equals("EXCHANGE")?"oms_exchange":"oms_order_shipment",field=type.equals("PLATFORM_EXCHANGE")?"dispute_id":type.equals("PLATFORM_TID")?"platform_tid":type.equals("OMS_ORDER")?"order_sn":type.equals("EXCHANGE")?"exchange_sn":"shipment_sn",state=businessType.equals("EXCHANGE")?"state":"status";List<Object> args=new ArrayList<>();args.add(company);args.addAll(values);for(Map<String,Object> row:repository.db().query("SELECT id,"+field+" number,"+state+" state"+(businessType.equals("EXCHANGE")?",control_state,exchange_sn,channel_id,source_kind,dispute_id,linked_exchange_id,platform_status,platform_operation,fulfillment_mode,fulfillment_round,requested_quantity,approved_version,fulfillment_hold,speed_exchange,stage,return_qc":"")+" FROM "+table+" WHERE company_code=? AND "+field+" IN ("+String.join(",",Collections.nCopies(values.size(),"?"))+")",ROW,args.toArray())){row.put("type",type);row.put("business_type",businessType);result.add(row);}}List<Map<String,Object>> cases=new ArrayList<>();for(Map<String,Object> r:result)if("EXCHANGE".equals(r.get("business_type")))cases.add(r);ExchangePlatformProgress.enrich(repository.db(),company,cases);return result;}
}
